import math
def interp(a,x):
    a=sorted(a)
    for p,q in zip(a,a[1:]):
        if p[0]<=x<=q[0] and q[0]-p[0]>0.02:
            return p[1]+(q[1]-p[1])*(x-p[0])/(q[0]-p[0])
    return None
def control(obs):
    h=obs['hitch_deg']
    cam=obs['views'].get('camera')
    if not cam: return (h,0,-23)
    left=[]; right=[]
    heading=obs['rig']['trailer_heading_deg']
    for b,d in cam['walls']:
        a=math.radians(b-heading)
        s=-d*math.cos(a); y=d*math.sin(a)
        if s>0.2:
            (left if y>0 else right).append((s,y))
    centers=[]
    for s in (2.0,2.5,3.0,3.5,4.0):
        l=interp(left,s); r=interp(right,s)
        if l is not None and r is not None: centers.append((s,(l+r)/2))
    if not centers: return (h,0,-23)
    s,y=min(centers,key=lambda p:abs(p[0]-3.5))
    desired=max(-28,min(28,math.degrees(math.atan2(5.2*y,s*s))))
    eq=math.degrees(math.atan2(2.75*math.sin(math.radians(h)),2.6+1.05*math.cos(math.radians(h))))
    steer=max(-34,min(34,eq+2.2*(h-desired)))
    return (steer,-0.75,-23)

